export class AuditPanel {
  private readonly audit = inject(AuditLog);
  private readonly session = inject(Session);
  protected readonly filter = signal('');
  protected readonly error = signal<string | null>(null);
  private readonly shown = signal<{ sheet: string | null; lines: string[] }>({ sheet: null, lines: [] });
  /** The lines last shown, while they are of the sheet loaded now. */
  protected readonly lines = computed(() => {
    const s = this.shown();
    return s.sheet === this.session.sheetId() ? s.lines : [];
  });
  private shows = 0;

  protected value(e: Event): string {
    return (e.target as HTMLInputElement).value;
  }

  protected async show(e: Event): Promise<void> {
    e.preventDefault();
    const show = ++this.shows;
    const sheet = this.session.sheetId();
    this.error.set(null);
    this.shown.set({ sheet: null, lines: [] });
    const res = await this.audit.lines(this.filter());
    if (show !== this.shows) return; // a later press has taken over
    if ('error' in res) this.error.set(res.error);
    else this.shown.set({ sheet, lines: res.lines });
  }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from './session';

// The active sheet's audit lines, read back from the audit file as it holds them now.
@Injectable({ providedIn: 'root' })
export class AuditLog {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The sheet's audit lines, newest first; with a name, only those about that person. An error message when that failed. */
  async lines(name: string): Promise<{ lines: string[] } | { error: string }> {
    const user = this.session.user();
    const sid = this.session.sheetId();
    if (!user || !sid) return { error: 'Load a sheet first.' };
    try {
      const lines = await firstValueFrom(
        this.http.get<string[]>(`/api/sheets/${encodeURIComponent(sid)}/audit`, {
          headers: { 'X-User': user },
          params: { name: name.trim() },
        }),
      );
      return { lines };
    } catch (e) {
      return { error: e instanceof HttpErrorResponse ? `Could not read the audit (${e.status}).` : 'Could not read the audit.' };
    }
  }
}
